"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2116],{7522(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part3-agent-protocols/langchain-langgraph-flowise","title":"LangChain to LangGraph to Flowise: Dictionaries, Nodes, and State","description":"How to think in \u201cpassing dictionaries\u201d, building nodes, composing runnables, managing state, and then turning it into a UI flow.","source":"@site/docs/part3-agent-protocols/07-langchain-langgraph-flowise.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/07-langchain-langgraph-flowise","permalink":"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":7,"frontMatter":{"title":"LangChain to LangGraph to Flowise: Dictionaries, Nodes, and State","slug":"/part3-agent-protocols/07-langchain-langgraph-flowise","description":"How to think in \u201cpassing dictionaries\u201d, building nodes, composing runnables, managing state, and then turning it into a UI flow.","sidebar_label":"7. LangChain, LangGraph, and Flowise","pagination_label":"7. LangChain, LangGraph, and Flowise","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"6. JavaScript and TypeScript primer","permalink":"/tutorials/part3-agent-protocols/06-javascript-typescript-primer"},"next":{"title":"Part overview","permalink":"/tutorials/part4-ml-foundations/overview"}}');var i=n(4848),s=n(8453),r=n(8172);const o=JSON.parse('{"sourcePath":"part3-agent-protocols/07-langchain-langgraph-flowise.html","route":"/part3-agent-protocols/07-langchain-langgraph-flowise","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"LangChain \u2192 LangGraph \u2192 Flowise","title":"LangChain to LangGraph to Flowise: Dictionaries, Nodes, and State","description":"How to think in \u201cpassing dictionaries\u201d, building nodes, composing runnables, managing state, and then turning it into a UI flow.","readingMinutes":9,"bodyClass":"","normalizeMath":false,"toc":[{"id":"bridge-from-http-dict-pipelines","label":"Bridge from HTTP \u2192 \u201cdict pipelines\u201d"},{"id":"langchain-everything-is-a-runnable-that-transforms-inputs-outputs","label":"LangChain: everything is a runnable that transforms inputs \u2192 outputs"},{"id":"langgraph-stateful-graphs-state-partial-state","label":"LangGraph: stateful graphs (State \u2192 partial State)"},{"id":"flowise-visual-applications-and-agentflow-v2","label":"Flowise: visual applications and Agentflow V2"},{"id":"extension-path","label":"Extension path"}],"html":"<header>\\n  <div class=\\"wrap\\">\\n    \\n    <p class=\\"muted\\">How to think in \u201cpassing dictionaries\u201d, building nodes, composing runnables, managing state, and then turning it into a UI flow.</p>\\n\\n    <div class=\\"toc\\">\\n      <strong>Table of contents</strong>\\n      <ul>\\n        <li><a href=\\"#bridge\\">Bridge from HTTP \u2192 \u201cdict pipelines\u201d</a></li>\\n        <li><a href=\\"#langchain\\">LangChain: everything is a runnable that transforms inputs \u2192 outputs</a>\\n          <ul>\\n            <li><a href=\\"#dicts\\">The \u201cpassing dictionaries\u201d mental model</a></li>\\n            <li><a href=\\"#runnables\\">Runnables: invoke/batch/stream + composition</a></li>\\n            <li><a href=\\"#passthrough\\">RunnablePassthrough + assign</a></li>\\n            <li><a href=\\"#custom-node\\">Custom node creation (custom runnable)</a></li>\\n            <li><a href=\\"#mini-chain\\">Mini end-to-end chain example</a></li>\\n          </ul>\\n        </li>\\n        <li><a href=\\"#langgraph\\">LangGraph: stateful graphs (State \u2192 partial State)</a>\\n          <ul>\\n            <li><a href=\\"#state\\">State passing and reducers</a></li>\\n            <li><a href=\\"#graph-example\\">Example: \u201cpurchase request\u201d graph (inventory + approval)</a></li>\\n          </ul>\\n        </li>\\n        <li><a href=\\"#flowise\\">Flowise: visual applications and Agentflow V2</a></li>\\n      </ul>\\n    </div>\\n  </div>\\n</header>\\n\\n<main class=\\"wrap\\">\\n\\n  <div class=\\"tr-update\\">\\n    <strong>Framework status</strong>\\n    The runnable and <code>StateGraph</code> examples in this chapter remain\\n    current. In LangChain v1, <code>langchain.agents.create_agent</code> is the\\n    standard prebuilt agent API and replaces\\n    <code>langgraph.prebuilt.create_react_agent</code>. Use raw\\n    <code>StateGraph</code> when you need an explicit custom workflow. Flowise\\n    Agentflow V2 is a native orchestration system with standalone nodes and\\n    Flow State; it is not merely a visual skin over LangChain.\\n  </div>\\n\\n  <section id=\\"bridge\\">\\n    <h2 id=\\"bridge-from-http-dict-pipelines\\">Bridge from HTTP \u2192 \u201cdict pipelines\u201d</h2>\\n    <p>\\n      You already learned HTTP methods (GET/POST/PUT/PATCH/DELETE). When you build LLM apps, you\u2019ll usually expose them as HTTP endpoints too.\\n      The key connection:\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>HTTP request body is typically JSON \u2192 in Python it becomes a <code class=\\"inline\\">dict</code>.</strong><br>\\n      LangChain/LangGraph pipelines are easiest to understand as \u201cfunctions that transform dictionaries\u201d.\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <div class=\\"diagram\\">\\n        Client JSON<br>\\n        \u2514\u2500&gt; Python dict<br>\\n            \u2514\u2500&gt; LangChain runnable pipeline (dict -&gt; dict/string)<br>\\n                \u2514\u2500&gt; HTTP JSON response\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>Visual: request \u2192 dict \u2192 runnable pipeline</strong>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 220\\" role=\\"img\\" aria-label=\\"HTTP request to dict to runnable pipeline to response\\">\\n        <defs>\\n          <marker id=\\"arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n            <path d=\\"M 0 0 L 10 5 L 0 10 z\\" class=\\"accentFill\\" fill=\\"#0969da\\" stroke=\\"none\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <rect x=\\"18\\" y=\\"48\\" width=\\"200\\" height=\\"120\\" rx=\\"14\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"118\\" y=\\"86\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Client</text>\\n        <text x=\\"118\\" y=\\"112\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">JSON body</text>\\n        <text x=\\"118\\" y=\\"136\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">{...}</text>\\n\\n        <rect x=\\"260\\" y=\\"48\\" width=\\"200\\" height=\\"120\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"360\\" y=\\"86\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Python</text>\\n        <text x=\\"360\\" y=\\"112\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">dict</text>\\n        <text x=\\"360\\" y=\\"136\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">{\\"question\\": ...}</text>\\n\\n        <rect x=\\"502\\" y=\\"48\\" width=\\"260\\" height=\\"120\\" rx=\\"14\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"632\\" y=\\"78\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">LangChain</text>\\n        <text x=\\"632\\" y=\\"105\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">Runnable pipeline</text>\\n        <text x=\\"632\\" y=\\"132\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">prompt | llm | parser</text>\\n\\n        <rect x=\\"804\\" y=\\"48\\" width=\\"160\\" height=\\"120\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"884\\" y=\\"86\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Response</text>\\n        <text x=\\"884\\" y=\\"112\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">JSON / text</text>\\n        <text x=\\"884\\" y=\\"136\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">\\"...\\"</text>\\n\\n        <line x1=\\"218\\" y1=\\"108\\" x2=\\"260\\" y2=\\"108\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n        <line x1=\\"460\\" y1=\\"108\\" x2=\\"502\\" y2=\\"108\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n        <line x1=\\"762\\" y1=\\"108\\" x2=\\"804\\" y2=\\"108\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n\\n        <text x=\\"240\\" y=\\"95\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">parse</text>\\n        <text x=\\"481\\" y=\\"95\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">invoke</text>\\n        <text x=\\"783\\" y=\\"95\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">return</text>\\n      </svg>\\n      <p class=\\"muted\\">This is the \u201cdict pipeline\u201d mental model: you\u2019re always passing one structured object through transforms.</p>\\n    </div>\\n  </section>\\n\\n  <section id=\\"langchain\\">\\n    <h2 id=\\"langchain-everything-is-a-runnable-that-transforms-inputs-outputs\\">LangChain: everything is a runnable that transforms inputs \u2192 outputs</h2>\\n\\n    <section id=\\"dicts\\">\\n      <h3 id=\\"1-the-passing-dictionaries-mental-model\\">1) The \u201cpassing dictionaries\u201d mental model</h3>\\n      <p>\\n        Think of a chain as a pipeline that receives a dictionary, adds/changes keys, and eventually returns a final output.\\n      </p>\\n\\n      <div class=\\"grid\\">\\n        <div class=\\"card\\">\\n          <strong>Input dict</strong>\\n          <pre><code class=\\"language-json\\">{\\n  \\"user_id\\": \\"u_123\\",\\n  \\"question\\": \\"What is my total spend last month?\\"\\n}</code></pre>\\n        </div>\\n        <div class=\\"card\\">\\n          <strong>Output</strong>\\n          <pre><code class=\\"language-json\\">\\"Your total spend last month was $1,245.40\\"</code></pre>\\n        </div>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Internally, intermediate steps might create keys like <code class=\\"inline\\">sql</code>, <code class=\\"inline\\">rows</code>, <code class=\\"inline\\">summary</code>.\\n      </p>\\n    </section>\\n\\n    <section id=\\"runnables\\">\\n      <h3 id=\\"2-runnables-one-interface-composition\\">2) Runnables: one interface + composition</h3>\\n      <p>\\n        A <span class=\\"badge\\">Runnable</span> is \u201canything\u201d you can call in a consistent way:\\n        one input \u2192 one output.\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr><th>Concept</th><th>What it means</th><th>Why you care</th></tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><code class=\\"inline\\">invoke(input)</code></td>\\n            <td>Run once, return output</td>\\n            <td>Simple request/response</td>\\n          </tr>\\n          <tr>\\n            <td><code class=\\"inline\\">batch([inputs])</code></td>\\n            <td>Run many inputs efficiently</td>\\n            <td>Lower cost + faster throughput</td>\\n          </tr>\\n          <tr>\\n            <td><code class=\\"inline\\">stream(input)</code></td>\\n            <td>Yield partial outputs as they\u2019re produced</td>\\n            <td>Great UX for chat/long responses</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"card\\">\\n        <strong>Composition rule (LCEL):</strong> pipe output of one runnable into the next\\n        <div class=\\"diagram\\" style=\\"margin-top:10px;\\">\\n          prompt_template | llm | output_parser\\n        </div>\\n        <p class=\\"muted\\">\\n          Mentally: <code class=\\"inline\\">output = parser(llm(prompt(input)))</code>\\n        </p>\\n      </div>\\n\\n      <div class=\\"callout good\\">\\n        <strong>Why this \u201cuniform runnable\u201d idea is powerful:</strong><br>\\n        Once everything speaks the same interface, you can mix-and-match prompts, models, retrievers, parsers, and custom logic like LEGO.\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Visual: one interface, different runtimes</strong>\\n        <svg class=\\"viz\\" viewBox=\\"0 0 980 220\\" role=\\"img\\" aria-label=\\"Runnable invoke batch stream visual\\">\\n          <defs>\\n            <marker id=\\"arrow2\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n              <path d=\\"M 0 0 L 10 5 L 0 10 z\\" class=\\"accent2Fill\\" fill=\\"#8250df\\" stroke=\\"none\\"></path>\\n            </marker>\\n          </defs>\\n\\n          <rect x=\\"30\\" y=\\"64\\" width=\\"240\\" height=\\"120\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"150\\" y=\\"98\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Runnable</text>\\n          <text x=\\"150\\" y=\\"126\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">one input \u2192 one output</text>\\n          <text x=\\"150\\" y=\\"154\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">uniform interface</text>\\n\\n          <rect x=\\"320\\" y=\\"30\\" width=\\"200\\" height=\\"60\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"420\\" y=\\"66\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">invoke</text>\\n\\n          <rect x=\\"320\\" y=\\"98\\" width=\\"200\\" height=\\"60\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"420\\" y=\\"134\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">batch</text>\\n\\n          <rect x=\\"320\\" y=\\"166\\" width=\\"200\\" height=\\"60\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"420\\" y=\\"202\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">stream</text>\\n\\n          <rect x=\\"580\\" y=\\"30\\" width=\\"370\\" height=\\"196\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"765\\" y=\\"66\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Composition</text>\\n          <text x=\\"765\\" y=\\"102\\" text-anchor=\\"middle\\" class=\\"label\\" fill=\\"#334155\\">prompt | llm | parser</text>\\n          <text x=\\"765\\" y=\\"134\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">mix-and-match components</text>\\n          <text x=\\"765\\" y=\\"170\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">same call shape everywhere</text>\\n\\n          <line x1=\\"270\\" y1=\\"124\\" x2=\\"320\\" y2=\\"60\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow2)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <line x1=\\"270\\" y1=\\"124\\" x2=\\"320\\" y2=\\"128\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow2)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <line x1=\\"270\\" y1=\\"124\\" x2=\\"320\\" y2=\\"196\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow2)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <line x1=\\"520\\" y1=\\"128\\" x2=\\"580\\" y2=\\"128\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow2)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n        </svg>\\n      </div>\\n    </section>\\n\\n    <section id=\\"passthrough\\">\\n      <h3 id=\\"3-runnablepassthrough-and-keeping-keys-alive\\">3) RunnablePassthrough (and \u201ckeeping keys alive\u201d)</h3>\\n      <p>\\n        In real pipelines you often need to compute something new <em>without losing the original input</em>.\\n        That\u2019s where \u201cpassthrough\u201d patterns help.\\n      </p>\\n\\n      <div class=\\"card\\">\\n        <strong>Typical RAG shape (conceptual)</strong>\\n        <pre><code class=\\"language-json\\">{\\n  \\"question\\": \\"...\\",\\n  \\"context\\": \\"&lt;retrieved docs text&gt;\\"\\n}  --&gt; prompt --&gt; llm --&gt; answer</code></pre>\\n      </div>\\n\\n      <p>\\n        <code class=\\"inline\\">RunnablePassthrough</code> behaves like identity, and can also be used with an \u201cassign\u201d pattern to add keys.\\n      </p>\\n\\n      <pre><code class=\\"language-python\\"># Conceptual example (LangChain LCEL style)\\nfrom operator import itemgetter\\nfrom langchain_core.runnables import RunnablePassthrough\\n\\n# Suppose you already have: retriever, format_docs, prompt, llm, parser\\nsetup = RunnablePassthrough.assign(\\n    context=itemgetter(\\"question\\") | retriever | format_docs\\n)\\n\\nchain = setup | prompt | llm | parser\\n\\nresult = chain.invoke({\\"question\\": \\"What are the top 3 products by revenue?\\"})\\nprint(result)</code></pre>\\n\\n      <div class=\\"callout\\">\\n        <strong>Key mental model:</strong> Passthrough keeps your dict intact, while letting you attach extra computed fields.\\n      </div>\\n    </section>\\n\\n    <section id=\\"custom-node\\">\\n      <h3 id=\\"4-custom-node-creation-in-langchain-custom-runnable\\">4) Custom node creation in LangChain (custom runnable)</h3>\\n      <p>\\n        \u201cNode\u201d isn\u2019t an official LangChain term the way it is in graph frameworks, but developers often call each pipeline step a \u201cnode\u201d.\\n        The simplest way to create a custom node is to wrap a Python function as a runnable.\\n      </p>\\n\\n      <pre><code class=\\"language-python\\">from langchain_core.runnables import RunnableLambda\\n\\ndef normalize_question(inputs: dict) -&gt; dict:\\n    q = inputs[\\"question\\"].strip()\\n    return {**inputs, \\"question\\": q}\\n\\nnormalize_node = RunnableLambda(normalize_question)\\n\\n# Now it composes like any other runnable:\\n# normalize_node | prompt | llm | parser</code></pre>\\n\\n      <div class=\\"card\\">\\n        <strong>Rule of thumb</strong>\\n        <ul>\\n          <li>Input and output can be strings, lists, or dicts\u2026 but dicts give you the most flexibility.</li>\\n          <li>Prefer \u201cpure transforms\u201d (no side effects) for easy debugging.</li>\\n          <li>If you need side effects (DB writes, HTTP calls), isolate them in a clearly-named node.</li>\\n        </ul>\\n      </div>\\n    </section>\\n\\n    <section id=\\"mini-chain\\">\\n      <h3 id=\\"5-mini-end-to-end-langchain-example-sql-helper-dict-first\\">5) Mini end-to-end LangChain example (SQL helper, dict-first)</h3>\\n      <p>\\n        Here\u2019s a tiny pipeline that:\\n        1) builds SQL from a question, 2) executes it, 3) summarizes rows.\\n        This is intentionally small so you can \u201csee the dictionaries move\u201d.\\n      </p>\\n\\n      <pre><code class=\\"language-python\\">from langchain_core.runnables import RunnableLambda, RunnablePassthrough\\nfrom operator import itemgetter\\n\\n# --- pretend implementations ---\\ndef llm_write_sql(inputs: dict) -&gt; dict:\\n    # In practice: prompt | llm | parser\\n    q = inputs[\\"question\\"]\\n    sql = \\"SELECT SUM(amount) AS total FROM orders WHERE order_month = :month\\"\\n    params = {\\"month\\": \\"last\\"}\\n    return {**inputs, \\"sql\\": sql, \\"params\\": params, \\"question_echo\\": q}\\n\\ndef run_sql(inputs: dict) -&gt; dict:\\n    # In practice: call your DB driver here with bound parameters, not string interpolation.\\n    rows = [{\\"total\\": 1245.40}]\\n    return {**inputs, \\"rows\\": rows}\\n\\ndef summarize(inputs: dict) -&gt; str:\\n    total = inputs[\\"rows\\"][0][\\"total\\"]\\n    return f\\"Your total spend last month was ${total:,.2f}\\"\\n\\n# --- wrap as nodes ---\\nwrite_sql = RunnableLambda(llm_write_sql)\\nexecute = RunnableLambda(run_sql)\\nsummarize_node = RunnableLambda(summarize)\\n\\n# --- keep dict, add keys, finish with a string ---\\nchain = (\\n    RunnablePassthrough()   # starts as identity (keeps original dict)\\n    | write_sql             # adds sql\\n    | execute               # adds rows\\n    | summarize_node        # returns final string\\n)\\n\\nprint(chain.invoke({\\"user_id\\": \\"u_123\\", \\"question\\": \\"What is my total spend last month?\\"}))</code></pre>\\n\\n      <div class=\\"callout good\\">\\n        <strong>What you should notice:</strong><br>\\n        Each step either (a) returns a new dict with extra keys, or (b) returns the final answer.\\n        That\u2019s the \u201cpassing dictionaries\u201d idea in one page.\\n      </div>\\n    </section>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"langgraph\\">\\n    <h2 id=\\"langgraph-stateful-graphs-state-partial-state\\">LangGraph: stateful graphs (State \u2192 partial State)</h2>\\n\\n    <section id=\\"state\\">\\n      <h3 id=\\"1-state-passing\\">1) State passing</h3>\\n      <p>\\n        LangGraph is what you use when a simple linear chain becomes a workflow:\\n        branching, loops, retries, tool-calling cycles, or multi-step \u201cagent\u201d behavior.\\n      </p>\\n\\n      <div class=\\"card\\">\\n        <strong>Core rule:</strong>\\n        <div class=\\"diagram\\" style=\\"margin-top:10px;\\">\\n          Each node reads State and returns a partial update to State\\n        </div>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Visual: State \u2192 partial State updates</strong>\\n        <svg class=\\"viz\\" viewBox=\\"0 0 980 240\\" role=\\"img\\" aria-label=\\"State passing visual\\">\\n          <defs>\\n            <marker id=\\"arrow3\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n              <path d=\\"M 0 0 L 10 5 L 0 10 z\\" class=\\"accentFill\\" fill=\\"#0969da\\" stroke=\\"none\\"></path>\\n            </marker>\\n          </defs>\\n\\n          <rect x=\\"30\\" y=\\"60\\" width=\\"260\\" height=\\"140\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"160\\" y=\\"96\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">State (shared)</text>\\n          <text x=\\"160\\" y=\\"128\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">{\\"sku\\", \\"qty\\", \\"amount\\", ...}</text>\\n          <text x=\\"160\\" y=\\"156\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">+ intermediate keys</text>\\n\\n          <rect x=\\"360\\" y=\\"24\\" width=\\"260\\" height=\\"76\\" rx=\\"14\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"58\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">node A</text>\\n          <text x=\\"490\\" y=\\"84\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">returns {\\"in_stock\\": true}</text>\\n\\n          <rect x=\\"360\\" y=\\"126\\" width=\\"260\\" height=\\"76\\" rx=\\"14\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"160\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">node B</text>\\n          <text x=\\"490\\" y=\\"186\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">returns {\\"approval\\": \\"approved\\"}</text>\\n\\n          <rect x=\\"690\\" y=\\"60\\" width=\\"260\\" height=\\"140\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"820\\" y=\\"96\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Merged State</text>\\n          <text x=\\"820\\" y=\\"128\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">State + updates</text>\\n          <text x=\\"820\\" y=\\"156\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">(reducers define merging)</text>\\n\\n          <line x1=\\"290\\" y1=\\"130\\" x2=\\"360\\" y2=\\"62\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow3)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n          <line x1=\\"290\\" y1=\\"130\\" x2=\\"360\\" y2=\\"164\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow3)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n          <line x1=\\"620\\" y1=\\"62\\" x2=\\"690\\" y2=\\"130\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow3)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n          <line x1=\\"620\\" y1=\\"164\\" x2=\\"690\\" y2=\\"130\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow3)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n        </svg>\\n      </div>\\n\\n      <p>\\n        You usually define a typed state (e.g., <code class=\\"inline\\">TypedDict</code>) and each node returns only the keys it changed.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <strong>Reducers (why they exist):</strong><br>\\n        If multiple nodes update the same key (e.g., message history), reducers define how those updates are merged (append, overwrite, etc.).\\n      </div>\\n    </section>\\n\\n    <section id=\\"graph-example\\">\\n      <h3 id=\\"2-example-purchase-request-graph-inventory-approval\\">2) Example: \u201cpurchase request\u201d graph (inventory + approval)</h3>\\n      <p>\\n        This mirrors the A2A story you built earlier (concierge \u2192 inventory + approval),\\n        but inside a single LangGraph workflow with shared state.\\n      </p>\\n\\n      <div class=\\"card\\">\\n        <strong>Graph shape</strong>\\n        <div class=\\"diagram\\">\\n          START\\n            |\\n         parse_request\\n            |\\n        check_inventory ----(out_of_stock)----&gt; finalize\\n            |\\n        request_approval ----(rejected)-------&gt; finalize\\n            |\\n          finalize\\n            |\\n           END\\n        </div>\\n      </div>\\n\\n      <div class=\\"card\\">\\n        <strong>Visual: branching workflow</strong>\\n        <svg class=\\"viz\\" viewBox=\\"0 0 980 292\\" role=\\"img\\" aria-label=\\"Purchase request graph visual\\">\\n          <defs>\\n            <marker id=\\"arrow4\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n              <path d=\\"M 0 0 L 10 5 L 0 10 z\\" class=\\"accent2Fill\\" fill=\\"#8250df\\" stroke=\\"none\\"></path>\\n            </marker>\\n          </defs>\\n\\n          <rect x=\\"410\\" y=\\"20\\" width=\\"160\\" height=\\"44\\" rx=\\"12\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"48\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">START</text>\\n\\n          <rect x=\\"370\\" y=\\"84\\" width=\\"240\\" height=\\"50\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"114\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">parse_request</text>\\n\\n          <rect x=\\"350\\" y=\\"154\\" width=\\"280\\" height=\\"52\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"186\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">check_inventory</text>\\n\\n          <rect x=\\"100\\" y=\\"214\\" width=\\"260\\" height=\\"46\\" rx=\\"12\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"230\\" y=\\"242\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">finalize</text>\\n          <text x=\\"230\\" y=\\"262\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">(out_of_stock)</text>\\n\\n          <rect x=\\"620\\" y=\\"214\\" width=\\"260\\" height=\\"46\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"750\\" y=\\"242\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">request_approval</text>\\n\\n          <rect x=\\"410\\" y=\\"214\\" width=\\"160\\" height=\\"46\\" rx=\\"12\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n          <text x=\\"490\\" y=\\"242\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">finalize</text>\\n          <text x=\\"490\\" y=\\"262\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">(then END)</text>\\n\\n          <line x1=\\"490\\" y1=\\"64\\" x2=\\"490\\" y2=\\"84\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow4)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <line x1=\\"490\\" y1=\\"134\\" x2=\\"490\\" y2=\\"154\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow4)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n\\n          <line x1=\\"390\\" y1=\\"206\\" x2=\\"280\\" y2=\\"214\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow4)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <text x=\\"335\\" y=\\"216\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">no stock</text>\\n\\n          <line x1=\\"590\\" y1=\\"206\\" x2=\\"700\\" y2=\\"214\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow4)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <text x=\\"645\\" y=\\"216\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">in stock</text>\\n\\n          <line x1=\\"750\\" y1=\\"260\\" x2=\\"570\\" y2=\\"260\\" class=\\"accent2\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow4)\\" stroke=\\"#8250df\\" fill=\\"none\\"></line>\\n          <text x=\\"655\\" y=\\"252\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">approved/rejected \u2192 finalize</text>\\n        </svg>\\n      </div>\\n\\n      <pre><code class=\\"language-python\\">from typing import TypedDict, Literal, Optional\\nfrom langgraph.graph import StateGraph, END\\n\\nclass PurchaseState(TypedDict, total=False):\\n    # input\\n    sku: str\\n    qty: int\\n    amount: float\\n    po_id: str\\n\\n    # derived/intermediate\\n    in_stock: bool\\n    reserved: bool\\n    approval: Literal[\\"approved\\", \\"rejected\\", \\"skipped\\"]\\n    reason: Optional[str]\\n\\n    # final\\n    result: str\\n\\n# --- nodes ---\\ndef parse_request(state: PurchaseState) -&gt; PurchaseState:\\n    # In real life, parse from user text. Here we assume state already has fields.\\n    return {}\\n\\ndef check_inventory(state: PurchaseState) -&gt; PurchaseState:\\n    # pretend inventory lookup\\n    stock_map = {\\"SKU-APPLE\\": 12, \\"SKU-CHAIR\\": 0}\\n    available = stock_map.get(state[\\"sku\\"], 0)\\n    if available &lt; state[\\"qty\\"]:\\n        return {\\"in_stock\\": False, \\"reserved\\": False, \\"reason\\": f\\"Only {available} left\\"}\\n    return {\\"in_stock\\": True, \\"reserved\\": True}\\n\\ndef request_approval(state: PurchaseState) -&gt; PurchaseState:\\n    # pretend policy: auto-approve up to 1000\\n    if state[\\"amount\\"] &lt;= 1000:\\n        return {\\"approval\\": \\"approved\\"}\\n    return {\\"approval\\": \\"rejected\\", \\"reason\\": \\"Over auto-approval limit\\"}\\n\\ndef finalize(state: PurchaseState) -&gt; PurchaseState:\\n    if not state.get(\\"in_stock\\", True):\\n        return {\\"result\\": f\\"FAILED: out of stock ({state.get(\'reason\')})\\"}\\n    if state.get(\\"approval\\") == \\"rejected\\":\\n        return {\\"result\\": f\\"FAILED: approval rejected ({state.get(\'reason\')})\\"}\\n    return {\\"result\\": \\"SUCCESS: reserved and approved\\"}\\n\\n# --- build graph ---\\ng = StateGraph(PurchaseState)\\ng.add_node(\\"parse_request\\", parse_request)\\ng.add_node(\\"check_inventory\\", check_inventory)\\ng.add_node(\\"request_approval\\", request_approval)\\ng.add_node(\\"finalize\\", finalize)\\n\\ng.set_entry_point(\\"parse_request\\")\\ng.add_edge(\\"parse_request\\", \\"check_inventory\\")\\n\\n# conditional branching after inventory\\ndef inventory_router(state: PurchaseState):\\n    return \\"finalize\\" if not state.get(\\"in_stock\\", True) else \\"request_approval\\"\\n\\ng.add_conditional_edges(\\"check_inventory\\", inventory_router, {\\n    \\"finalize\\": \\"finalize\\",\\n    \\"request_approval\\": \\"request_approval\\",\\n})\\n\\n# conditional branching after approval\\ndef approval_router(state: PurchaseState):\\n    return \\"finalize\\"\\n\\ng.add_conditional_edges(\\"request_approval\\", approval_router, {\\n    \\"finalize\\": \\"finalize\\",\\n})\\n\\ng.add_edge(\\"finalize\\", END)\\n\\napp = g.compile()\\n\\nprint(app.invoke({\\"sku\\": \\"SKU-APPLE\\", \\"qty\\": 2, \\"amount\\": 4.50, \\"po_id\\": \\"PO-1001\\"})[\\"result\\"])\\nprint(app.invoke({\\"sku\\": \\"SKU-CHAIR\\", \\"qty\\": 1, \\"amount\\": 150.0, \\"po_id\\": \\"PO-2002\\"})[\\"result\\"])\\nprint(app.invoke({\\"sku\\": \\"SKU-APPLE\\", \\"qty\\": 1, \\"amount\\": 2500.0, \\"po_id\\": \\"PO-3003\\"})[\\"result\\"])</code></pre>\\n\\n      <div class=\\"callout good\\">\\n        <strong>Key difference vs LangChain chain:</strong><br>\\n        LangChain pipelines are typically linear transforms; LangGraph makes the \u201cworkflow control\u201d (branching/loops) explicit and stateful.\\n      </div>\\n\\n      <div class=\\"tr-note\\">\\n        <strong>Where the current prebuilt agent fits</strong>\\n        If your workflow is the standard model \u2192 tool calls \u2192 model loop, use\\n        <code>langchain.agents.create_agent</code>. It is implemented on\\n        LangGraph and can add middleware for guardrails, dynamic prompts,\\n        human approval, and state. Use the raw graph above when the business\\n        process itself has named states, deterministic branches, or custom\\n        persistence semantics.\\n      </div>\\n\\n      <pre><code class=\\"language-python\\">import os\\nfrom langchain.agents import create_agent\\n\\n# inventory_check is an ordinary LangChain tool defined elsewhere.\\nagent = create_agent(\\n    model=os.environ[\\"LANGCHAIN_MODEL\\"],\\n    tools=[inventory_check],\\n    system_prompt=\\"Check inventory before promising availability.\\",\\n)\\n\\nresult = agent.invoke({\\n    \\"messages\\": [\\n        {\\"role\\": \\"user\\", \\"content\\": \\"Can we supply two SKU-APPLE units?\\"}\\n    ]\\n})</code></pre>\\n    </section>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n\\n  <section id=\\"flowise\\">\\n    <h2 id=\\"flowise-visual-applications-and-agentflow-v2\\">Flowise: visual applications and Agentflow V2</h2>\\n\\n    <p>\\n      Flowise is an open-source visual platform for assistants, LLM\\n      applications, and agent workflows. Its three main builder levels are\\n      <strong>Assistant</strong> for the simplest configured agent,\\n      <strong>Chatflow</strong> for single-agent/chatbot and RAG flows, and\\n      <strong>Agentflow</strong> for single- or multi-agent orchestration. A\\n      simple Chatflow can resemble the runnable pipeline above, but that\\n      mapping is only the starting point.\\n    </p>\\n\\n    <div class=\\"grid\\">\\n      <div class=\\"card\\">\\n        <strong>In code (LangChain)</strong>\\n        <div class=\\"diagram\\" style=\\"margin-top:10px;\\">\\n          input dict<br>\\n          \u2514\u2500&gt; prompt | llm | parser<br>\\n          \u2514\u2500&gt; output\\n        </div>\\n      </div>\\n      <div class=\\"card\\">\\n        <strong>In UI (Flowise)</strong>\\n        <div class=\\"diagram\\" style=\\"margin-top:10px;\\">\\n          [Prompt Node] \u2192 [LLM Node] \u2192 [Output Parser Node]<br>\\n          (+ optional Retriever/Memory/Tools nodes)\\n        </div>\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <strong>Visual: code pipeline \u2194 UI nodes</strong>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 240\\" role=\\"img\\" aria-label=\\"Flowise mapping visual\\">\\n        <defs>\\n          <marker id=\\"arrow5\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto-start-reverse\\">\\n            <path d=\\"M 0 0 L 10 5 L 0 10 z\\" class=\\"accentFill\\" fill=\\"#0969da\\" stroke=\\"none\\"></path>\\n          </marker>\\n        </defs>\\n\\n        <text x=\\"240\\" y=\\"34\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">LangChain (code)</text>\\n        <text x=\\"740\\" y=\\"34\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Flowise (UI)</text>\\n\\n        <rect x=\\"70\\" y=\\"70\\" width=\\"340\\" height=\\"140\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n        <rect x=\\"520\\" y=\\"70\\" width=\\"390\\" height=\\"140\\" rx=\\"14\\" class=\\"box2\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\" stroke-width=\\"1.5\\"></rect>\\n\\n        <rect x=\\"95\\" y=\\"104\\" width=\\"110\\" height=\\"44\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"150\\" y=\\"132\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">prompt</text>\\n        <rect x=\\"220\\" y=\\"104\\" width=\\"90\\" height=\\"44\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"265\\" y=\\"132\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">llm</text>\\n        <rect x=\\"320\\" y=\\"104\\" width=\\"90\\" height=\\"44\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"365\\" y=\\"132\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">parser</text>\\n\\n        <line x1=\\"205\\" y1=\\"126\\" x2=\\"220\\" y2=\\"126\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow5)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n        <line x1=\\"310\\" y1=\\"126\\" x2=\\"320\\" y2=\\"126\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow5)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n\\n        <rect x=\\"555\\" y=\\"94\\" width=\\"140\\" height=\\"46\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"625\\" y=\\"123\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Prompt Node</text>\\n        <rect x=\\"705\\" y=\\"94\\" width=\\"120\\" height=\\"46\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"765\\" y=\\"123\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">LLM Node</text>\\n        <rect x=\\"835\\" y=\\"94\\" width=\\"150\\" height=\\"46\\" rx=\\"12\\" class=\\"box\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\" stroke-width=\\"1.5\\"></rect>\\n        <text x=\\"910\\" y=\\"123\\" text-anchor=\\"middle\\" class=\\"title\\" fill=\\"#1f2328\\">Parser Node</text>\\n\\n        <line x1=\\"695\\" y1=\\"117\\" x2=\\"705\\" y2=\\"117\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow5)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n        <line x1=\\"825\\" y1=\\"117\\" x2=\\"835\\" y2=\\"117\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#arrow5)\\" stroke=\\"#0969da\\" fill=\\"none\\"></line>\\n\\n        <text x=\\"240\\" y=\\"188\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">source controlled</text>\\n        <text x=\\"740\\" y=\\"188\\" text-anchor=\\"middle\\" class=\\"muted\\" fill=\\"#59636e\\">fast prototyping</text>\\n      </svg>\\n      <p class=\\"muted\\">A simple Chatflow can map closely to a code pipeline; Agentflow V2 adds its own explicit orchestration model.</p>\\n    </div>\\n\\n    <h3 id=\\"how-a-simple-flowise-flow-maps-to-passing-dictionaries\\">How a simple Flowise flow maps to \u201cpassing dictionaries\u201d</h3>\\n    <ul>\\n      <li>Each node performs a configured operation such as prompting a model, retrieving documents, calling a tool, transforming data, or replying.</li>\\n      <li>Edges are \u201cdata flow\u201d: output of one node becomes input to the next.</li>\\n      <li>Node settings in the UI become the parameters you\u2019d pass in code (model name, temperature, prompt template, etc.).</li>\\n    </ul>\\n\\n    <h3 id=\\"what-agentflow-v2-adds\\">What Agentflow V2 adds</h3>\\n    <ul>\\n      <li><strong>Native standalone nodes:</strong> the execution graph is defined explicitly rather than delegated entirely to an external agent framework.</li>\\n      <li><strong>Flow State:</strong> declare shared keys in the Start node, then let later nodes read or update those keys without threading every value through adjacent edges.</li>\\n      <li><strong>Control flow:</strong> conditions, loops, routing, deterministic Tool nodes, LLM-driven Agent nodes, and reusable subflows.</li>\\n      <li><strong>Human-in-the-loop:</strong> pause for approval or feedback, save a checkpoint, and resume the workflow instead of blocking a process in memory.</li>\\n      <li><strong>Operations:</strong> streaming execution updates, tracing, API deployment, and workspace/security controls are part of the platform surface.</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      <strong>Practical workflow:</strong><br>\\n      Decide where the maintained source of truth lives. A team may keep a\\n      Flowise Agentflow in versioned exported configuration, or implement the\\n      workflow directly in LangGraph code. Rebuilding the same flow twice\\n      creates drift. Whichever path you choose, add evaluation fixtures,\\n      approval tests, secret management, access control, tracing, and a\\n      promotion process before production.\\n    </div>\\n\\n    <h3 id=\\"where-langgraph-shows-up-in-ui-tools\\">Where LangGraph shows up in UI tools</h3>\\n    <p>\\n      LangGraph and Agentflow V2 solve overlapping orchestration problems at\\n      different abstraction and governance boundaries. LangGraph keeps the\\n      workflow in Python code with explicit state, reducers, checkpointers, and\\n      tests. Agentflow V2 exposes branches, loops, agent/tool nodes, human\\n      input, checkpoints, and Flow State in a visual platform. Choose based on\\n      ownership, deployment controls, extensibility, and testability rather\\n      than assuming one is only a prototype for the other.\\n    </p>\\n\\n    <div class=\\"card\\">\\n      <strong>Rule of thumb</strong>\\n      <ul>\\n        <li><strong>LangChain runnables:</strong> compose deterministic transforms and model calls.</li>\\n        <li><strong>LangChain <code>create_agent</code>:</strong> use the supported prebuilt model/tool agent loop.</li>\\n        <li><strong>LangGraph:</strong> use code-first graphs for custom workflow logic, persistence, and shared state.</li>\\n        <li><strong>Flowise:</strong> use Assistant, Chatflow, or Agentflow V2 when a governed visual platform is the intended runtime and authoring surface.</li>\\n      </ul>\\n    </div>\\n\\n    <h3 id=\\"official-references\\">Official references</h3>\\n    <ul>\\n      <li><a href=\\"https://docs.langchain.com/oss/python/releases/langchain-v1\\">LangChain v1 changes and <code>create_agent</code></a></li>\\n      <li><a href=\\"https://docs.langchain.com/oss/python/migrate/langgraph-v1\\">LangGraph v1 migration guide</a></li>\\n      <li><a href=\\"https://docs.langchain.com/oss/python/langgraph/graph-api\\">LangGraph Graph API</a></li>\\n      <li><a href=\\"https://docs.flowiseai.com/\\">Flowise official documentation</a></li>\\n      <li><a href=\\"https://docs.flowiseai.com/using-flowise/agentflowv2\\">Flowise Agentflow V2</a></li>\\n    </ul>\\n  </section>\\n\\n  <div class=\\"hr\\"></div>\\n  <section>\\n    <h2 id=\\"extension-path\\">Extension path</h2>\\n    <div class=\\"card\\">\\n      <ol>\\n        <li>Turn the LangChain mini SQL chain into a real HTTP endpoint (POST /ask) that accepts JSON dict input.</li>\\n        <li>Replace the fake DB function with a real SQL driver call.</li>\\n        <li>Add auth: JWT / API key / OAuth, just like we discussed earlier.</li>\\n        <li>Promote to LangGraph when you need branching (e.g., approval required only over $1000).</li>\\n      </ol>\\n    </div>\\n  </section>\\n\\n</main>"}'),l={title:"LangChain to LangGraph to Flowise: Dictionaries, Nodes, and State",slug:"/part3-agent-protocols/07-langchain-langgraph-flowise",description:"How to think in \u201cpassing dictionaries\u201d, building nodes, composing runnables, managing state, and then turning it into a UI flow.",sidebar_label:"7. LangChain, LangGraph, and Flowise",pagination_label:"7. LangChain, LangGraph, and Flowise",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},h=[];function p(e){return(0,i.jsx)(r.A,{content:o})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);